#![cfg(feature="player")]
#[path="support/audio_transitions.rs"]mod transitions;
#[path="support/rational_audio_seek.rs"]mod rational;
use fvid::audio::AudioStream;
use std::{io::Cursor,sync::{Arc,Mutex},time::Duration};
use rational::{collect,exact};
fn root()->std::path::PathBuf{std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/playback-errors/coded-audio-index-eof")}
fn bytes(n:&str)->Vec<u8>{std::fs::read(root().join(n)).unwrap()}
fn cases()->Vec<serde_json::Value>{serde_json::from_slice::<serde_json::Value>(&bytes("manifest.json")).unwrap()["cases"].as_array().unwrap().clone()}
fn stream(c:&serde_json::Value)->Box<dyn AudioStream>{let b=bytes(c["file"].as_str().unwrap());match c["kind"].as_str().unwrap(){"aac"=>Box::new(fvid::playback_aac::AacAudioReader::open(b.as_slice(),Default::default()).unwrap()),"flac"=>Box::new(fvid::playback_flac::FlacAudioReader::open(b.as_slice(),Default::default()).unwrap()),"mpeg"=>Box::new(fvid::playback_mp3::Mp3AudioReader::open(b.as_slice(),Default::default()).unwrap()),"dolby"=>Box::new(fvid::playback_ac3::Ac3AudioReader::open(b.as_slice(),Default::default()).unwrap()),"xm"=>Box::new(fvid::playback_xm::XmAudioReader::open(b.as_slice(),Default::default()).unwrap()),_=>unreachable!()}}
enum Index{Aac(fvid::container::adts::Aac),Flac(fvid_media::owned_flac::Flac),Mpeg(fvid_media::owned_mpeg_audio::Mp3),Dolby(fvid::playback_ac3::Ac3),Xm(fvid::container::xm::Module)}
impl Index{fn open(c:&serde_json::Value)->Self{let b=bytes(c["file"].as_str().unwrap());match c["kind"].as_str().unwrap(){"aac"=>Self::Aac(fvid::container::adts::Aac::parse(&b,&Default::default()).unwrap()),"flac"=>Self::Flac(fvid_media::owned_flac::Flac::parse(&b,&Default::default()).unwrap()),"mpeg"=>Self::Mpeg(fvid_media::owned_mpeg_audio::Mp3::parse(&b,&Default::default()).unwrap()),"dolby"=>Self::Dolby(fvid::playback_ac3::Ac3::parse(&b,&Default::default()).unwrap()),"xm"=>Self::Xm(fvid::container::xm::Module::parse(&b,&Default::default()).unwrap()),_=>unreachable!()}}fn len(&self)->usize{match self{Self::Aac(x)=>x.packets(),Self::Flac(x)=>x.packets(),Self::Mpeg(x)=>x.packets(),Self::Dolby(x)=>x.packets(),Self::Xm(x)=>x.packets()}}fn packet(&self,n:usize)->Vec<u8>{match self{Self::Aac(x)=>x.packet(n).to_vec(),Self::Flac(x)=>x.packet(n).to_vec(),Self::Mpeg(x)=>x.packet(n).to_vec(),Self::Dolby(x)=>x.packet(n).to_vec(),Self::Xm(x)=>x.packet(n)}}}
fn check(kind:&str){for c in cases().into_iter().filter(|c|c["kind"].as_str()==Some(kind)){let index=Index::open(&c);assert!(index.len()>0);let last=index.packet(index.len()-1);assert!(!last.is_empty());for n in [index.len(),index.len()+1,usize::MAX]{assert!(index.packet(n).is_empty(),"{}:index{n} repeats {} bytes",c["file"].as_str().unwrap(),index.packet(n).len());}assert_eq!(index.packet(index.len()-1),last);if kind=="xm"{assert_eq!(index.len(),2,"one row plus the valid release tail");}}}
#[test]fn aac_index_eof(){check("aac");}
#[test]fn flac_index_eof(){check("flac");}
#[test]fn mpeg_index_eof(){check("mpeg");}
#[test]fn dolby_index_eof(){check("dolby");}
#[test]fn xm_index_eof_keeps_valid_release_tail(){check("xm");}
#[test]fn owned_aac_index_eof(){let b=bytes("tone.aac");let a=fvid_media::owned_aac::adts::Aac::parse(&b,&Default::default()).unwrap();for n in [a.packets(),a.packets()+1,usize::MAX]{assert!(a.packet(n).is_empty(),"owned ADTS repeats final payload at{n}");}}
#[test]fn valid_payloads_decode_before_testing_index_boundaries(){for c in cases(){let index=Index::open(&c);assert!((0..index.len()).all(|n|!index.packet(n).is_empty()));let mut source=stream(&c);if c["kind"]!="xm"{let mut encoded=Vec::new();while let Some(p)=source.next_packet().unwrap(){encoded.extend(p.data);}assert_eq!((0..index.len()).flat_map(|n|index.packet(n)).collect::<Vec<_>>(),encoded);source.rewind();}let pcm=collect(&mut *source);assert!(!pcm.is_empty());assert!(pcm.iter().flat_map(|p|p.data.chunks_exact(4)).all(|b|f32::from_le_bytes(b.try_into().unwrap()).is_finite()));if c["kind"]!="xm" && c["file"]!="silence.mp1"{assert!(pcm.iter().flat_map(|p|p.data.chunks_exact(4)).any(|b|f32::from_le_bytes(b.try_into().unwrap())!=0.),"authored tone must decode audible PCM");}if c["kind"]=="xm"{assert_eq!(pcm.iter().map(|p|p.frames()).sum::<usize>(),1764);assert!(pcm.iter().all(|p|p.data.iter().all(|&b|b==0)));}if c["file"]=="silence.mp1"{assert_eq!(pcm.iter().map(|p|p.frames()).sum::<usize>(),1152);assert!(pcm.iter().all(|p|p.data.iter().all(|&b|b==0)));}}let mut v=fvid::playback_native::NativeReader::software(Cursor::new(bytes("neutral-video.mp4")),32<<20).unwrap();for _ in 0..6{assert_eq!(v.read_frame_raw().unwrap().unwrap().into_rgb(32<<20).unwrap(),vec![130;16*16*3]);}assert!(v.read_frame_raw().unwrap().is_none());}
#[test]fn actual_workers_preserve_valid_pcm_and_native_stamps(){use fvid::audio_thread::AudioPlayback;use transitions::{Capture,Trace,ended};for c in cases(){let expected=collect(&mut *stream(&c));let raw=Arc::new(Mutex::new(rational::RawTrace::default()));let captured=raw.clone();let trace=Arc::new(Mutex::new(Trace::default()));let mut worker=AudioPlayback::start(stream(&c),move||Box::new(rational::RawCapture{inner:Capture::new(trace),raw:captured}));worker.seek(Duration::ZERO);worker.play();ended(&worker,worker.generation());let got=raw.lock().unwrap();exact(&got.packets,&expected,c["file"].as_str().unwrap());assert_eq!(got.anchors,vec![Duration::ZERO]);}}

#[test]fn provisional_streaminfo_is_separate_correct_refusal(){let b=bytes("provisional-streaminfo.flac");let error=fvid_media::owned_flac::Flac::parse(&b,&Default::default()).err().expect("provisional nonzero frame-size claim must refuse");assert!(error.to_string().contains("STREAMINFO states frame sizes"),"{error}");}
